Simplified a bit:

```js
import fastify from "fastify";

const ShowSchema = {
  $id: "ShowSchema",
  type: "object",
  properties: {
    name: { type: "string" },
  },
};
const ListSchema = {
  $id: "ListSchema",
  type: "array",
  items: { $ref: "ShowSchema" },
};

const app = fastify({
  logger: true,
});

app.addSchema(ListSchema);
app.addSchema(ShowSchema);

const defaultRouteOptions = {
  schema: { response: { 200: { $ref: "ListSchema" } } },
};

app.register(
  async (app) => {
    app.get("/resource/", defaultRouteOptions, () => ({}));
  },
  { prefix: "/prefix1" }
);
app.register(
  async (app) => {
    app.get("/resource/", defaultRouteOptions, () => ({}));
  },
  { prefix: "/prefix2" }
);

try {
  await app.listen(4000);
} catch (err) {
  app.log.error(err);
  process.exit(1);
}
```

What seems to be happening is that the route validation schema is hitting the following path:

1. https://github.com/fastify/fastify/blob/180be34f266e9f38d0fe0456fc6c84b87f7fe898/lib/schema-controller.js#L88
2. https://github.com/fastify/fastify/blob/180be34f266e9f38d0fe0456fc6c84b87f7fe898/lib/schema-compilers.js#L20
3. https://github.com/fastify/fastify/blob/180be34f266e9f38d0fe0456fc6c84b87f7fe898/lib/schema-compilers.js#L48

What I don't understand is why the validator needs its own AJV instance? Or is it re-using the root AJV instance and trying to re-add the referenced schema again? @Eomm
